expectedAnswer.referenceSolver:
def bewerte(lauf, schwellen):
    if lauf["status"] != "ok":
        return {"verdict": "abgebrochen", "pruefungen": []}
    min_subgruppe = min(lauf["subgruppen"].values()) if lauf["subgruppen"] else 0.0
    pruefungen = [
        {"name": "recall_at_k", "bestanden": lauf["recall_at_k"] >= schwellen["recall_min"], "ist": lauf["recall_at_k"], "soll": schwellen["recall_min"]},
        {"name": "subgruppe_min", "bestanden": min_subgruppe >= schwellen["subgruppe_min"], "ist": min_subgruppe, "soll": schwellen["subgruppe_min"]},
        {"name": "redteam_fixtures", "bestanden": lauf["fixtures_bestanden"] == lauf["fixtures_gesamt"], "ist": lauf["fixtures_bestanden"], "soll": lauf["fixtures_gesamt"]},
    ]
    verdict = "angenommen" if all(p["bestanden"] for p in pruefungen) else "abgelehnt"
    return {"verdict": verdict, "pruefungen": pruefungen}

# LAUF_OK -> angenommen (0.75/1.0&0.5/7von7); LAUF_SCHLECHT -> abgelehnt (0.3, 6von7)

